import { useState, useEffect, useRef } from "react";

function useFetchBatters<T>(): {
  data: T[];
  error: null | string;
  isLoading: boolean;
  refetch: (
    clearData: boolean,
    getTomorrow: boolean,
    signal?: AbortSignal
  ) => void;
  cancel: () => void;
} {
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<null | string>(null);
  const [data, setData] = useState<T[]>([]);
  const abortControllerRef = useRef<AbortController | null>(null); // ✅ Ref to abort controller

  const fetchTopBatters = async (
    clearData: boolean = false,
    getTomorrow: boolean = false,
    signal?: AbortSignal
  ) => {
    setIsLoading(true);
    setError(null); // Optional: reset error

    // If no signal provided, create one and store ref
    if (!signal) {
      abortControllerRef.current?.abort(); // cancel previous if any
      const newController = new AbortController();
      abortControllerRef.current = newController;
      signal = newController.signal;
    }

    try {
      const response = await fetch(
        `http://localhost:3001/api/scraper?clear=${clearData}&tomorrow=${getTomorrow}`,
        { signal }
      );

      if (!response.ok) {
        const text = await response.text();
        throw new Error(`Server error: ${response.status} - ${text}`);
      }

      const result: T[] = await response.json();
      setData(result);
    } catch (err: any) {
      if (err.name === "AbortError") {
        console.log("Fetch aborted");
      } else {
        console.log("Error fetching top batters:", err);
        setError("Error fetching top batters");
      }
    } finally {
      setIsLoading(false);
    }
  };

  const cancel = () => {
    abortControllerRef.current?.abort(); // ✅ abort fetch
    setIsLoading(false);
  };

  useEffect(() => {
    const controller = new AbortController();
    abortControllerRef.current = controller;
    fetchTopBatters(false, false, controller.signal);

    return () => {
      controller.abort();
    };
  }, []);

  return { data, error, isLoading, refetch: fetchTopBatters, cancel };
}

export default useFetchBatters;
